# Code generated by Claude
"""
Can geo_kin's collision ("safety") filter filter ROBOT joint positions?

The filter is part of the teleop solver, so its input is a human pose
(RetargetFrame). To use it on robot-side joint targets we have to turn joint
angles into the frame the solver expects, run solve(), and read the joints
back. This script tests that round trip with MuJoCo forward kinematics. It is
read-only (no viewer, no existing file changed) and runs headless.

    python experiments/safety_filter_roundtrip.py
    python experiments/safety_filter_roundtrip.py --seed 3 --n-free 20 --n-collide 8

What it does
  1. Builds the solver with collision_avoidance=True, functional_offset=False,
     retarget_mode="pose" (no human-to-robot adjustments).
  2. For a pair of 7-joint arm configs, computes S, E, W and the wrist rotation
     with MuJoCo FK (conventions below) and wraps them in a RetargetFrame.
  3. Collision-free test: random configs with no arm-to-arm or arm-to-torso
     contact (MuJoCo contacts). Reports the max joint error input -> output.
  4. Collision test: configs where the arms are crossed or touching. Reports
     whether the output is contact-free and how far each joint moved.
  5. Times every solve() call.

The conversion used for the tests is the shared helper src/safety_filter.py
(solver FK for S, E, W; R_link7 @ C for the wrist). This script keeps its own
MuJoCo-geometry conversion (Arms.frame, described below) as an independent
cross-check: --cross-check-n configs (default 600) compare the two. Use
--model-check to check the combined robot model (joint order by name, limits,
exact round trip from its angles).

Model: Kong's bundled OpenArm bimanual MJCF (openarm_teleop.model_path()), the
robot his solver spec was generated from. Its collision geoms have
contype=conaffinity=0 (kinematic replay), so this script switches them on in
memory (never written to disk) to get MuJoCo contacts. MuJoCo collides meshes
through their convex hulls, so contacts are slightly conservative.

FRAME CONVENTIONS (what is assumed, and how each was checked)
  * Solver ("SEW") frame: origin at openarm_body_link0 + (0, 0, 0.698), axes =
    link0 axes (x forward, y left, z up). This is openarm_teleop's
    MuJoCoController.get_sew_transform(), and it matches the solver's own
    safety capsules (sew_capsules()), whose shoulder capsule ends at
    (0, +-0.153, 0). RetargetFrame.R/p_world_upper_body is that frame's pose
    in the world; S, E, W are expressed in it (that is how the XRT device
    code builds them: body-centric coordinates).
  * S = the point where the axes of joints 1, 2 and 3 meet (they intersect, a
    spherical shoulder). Equals (0, +-0.1535, 0) in the solver frame and
    matches the solver's capsule endpoint.
  * W = origin of joint 7 (axes 5, 6 and 7 meet there: the wrist centre).
  * E = origin of joint 4 shifted by -0.0315 m along the joint-4 axis, i.e. the
    elbow point on the arm's centre line. Using the joint-4 origin itself
    left a systematic 0.11-0.14 rad error (about atan(0.0315 / 0.22), the
    elbow's lateral offset); the shifted point gives exactly zero error.
    Found by experiment against the solver, not read from Kong's code: the
    OpenArm session has no robot_fk diagnostic (that is Vega only).
  * Wrist rotation = R_body^T @ R_link7 @ C, with C = [[0,0,1],[0,-1,0],[1,0,0]]
    (R_body = link0 rotation). C maps the XRT human hand frame (x toward the
    fingers, y palm normal) onto the robot's link7 frame. Found by trying all
    24 axis-aligned rotations against the solver: it is the only one that
    works, for both arms. (The field is named R_world_wrist but the XRT code
    stores the BODY-frame rotation.)
  * CONTROL (test only): the same frames are also run through a second session
    with the filter OFF. Its error shows how exact the frame conversion is by
    itself, so any extra error with the filter on can be attributed to the
    filter. The teleop controller itself never disables the filter.
"""

import argparse
import sys
import time
from pathlib import Path

import mujoco
import numpy as np

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

from geo_kin_core.types import RetargetFrame, SEWPose  # noqa: E402
from openarm_teleop import model_path  # noqa: E402
from src.safety_filter import C_HAND, SafetyFilter  # noqa: E402

SEW_ORIGIN = np.array([0.0, 0.0, 0.698])   # solver frame origin above link0
ELBOW_SHIFT = 0.0315                       # m, along -joint4 axis
SIDES = ("left", "right")
np.set_printoptions(precision=3, suppress=True, linewidth=140)


# ---------------------------------------------------------------- model
class Arms:
    """MuJoCo model of the bimanual robot with kinematics and contact checks."""

    def __init__(self, model=None, contacts=True):
        self.m = mujoco.MjModel.from_xml_path(
            str(model_path() if model is None else model))
        self.d = mujoco.MjData(self.m)
        self.base = self.m.body("openarm_body_link0").id
        self.qadr = {s: [self.m.jnt_qposadr[self.m.joint(f"openarm_{s}_joint{i}").id]
                         for i in range(1, 8)] for s in SIDES}
        jids = {s: [self.m.joint(f"openarm_{s}_joint{i}").id for i in range(1, 8)]
                for s in SIDES}
        self.lo = {s: self.m.jnt_range[jids[s], 0] for s in SIDES}
        self.hi = {s: self.m.jnt_range[jids[s], 1] for s in SIDES}
        # Collision-class geoms (group 3) have contype=conaffinity=0 in the
        # MJCF; enable them in memory so mj_collision reports contacts.
        self.col_geoms = [g for g in range(self.m.ngeom)
                          if contacts and self.m.geom_group[g] == 3]
        for g in self.col_geoms:
            self.m.geom_contype[g] = 1
            self.m.geom_conaffinity[g] = 1
        # MuJoCo culls collision candidates with per-BODY masks computed at
        # compile time, so the geom masks alone are not enough.
        if contacts:
            self.m.body_contype[:] = 1
            self.m.body_conaffinity[:] = 1
        self.owner = {g: self._owner(g) for g in self.col_geoms}
        # Pairs for the clearance measure. Link 0 (mount) and link 1 (shoulder
        # yaw) hardly move and sit close to the torso and each other at every
        # pose, so they would hide the real clearance; leave them out here.
        mount = lambda g: self.m.body(self.m.geom_bodyid[g]).name.endswith(
            ("_link0", "_link1"))
        L = [g for g in self.col_geoms if self.owner[g] == "left"]
        R = [g for g in self.col_geoms if self.owner[g] == "right"]
        T = [g for g in self.col_geoms if self.owner[g] == "torso"]
        self.pairs_arm_arm = [(a, b) for a in L for b in R
                              if not mount(a) and not mount(b)]
        self.pairs_arm_torso = [(a, b) for a in L + R for b in T if not mount(a)]

    def _owner(self, g):
        name = self.m.body(self.m.geom_bodyid[g]).name
        if name.startswith("openarm_left"):
            return "left"
        if name.startswith("openarm_right"):
            return "right"
        return "torso"

    def set_q(self, ql, qr):
        mujoco.mj_resetData(self.m, self.d)
        self.d.qpos[self.qadr["left"]] = ql
        self.d.qpos[self.qadr["right"]] = qr
        mujoco.mj_forward(self.m, self.d)

    # ---- kinematics -> solver frame
    def _R_base(self):
        return self.d.xmat[self.base].reshape(3, 3)

    def to_sew(self, p_world):
        return self._R_base().T @ (p_world - self.d.xpos[self.base]) - SEW_ORIGIN

    def _shoulder(self, side):
        A, b = np.zeros((3, 3)), np.zeros(3)
        for i in (1, 2, 3):
            j = self.m.joint(f"openarm_{side}_joint{i}").id
            a = self.d.xaxis[j]
            P = np.eye(3) - np.outer(a, a)
            A += P
            b += P @ self.d.xanchor[j]
        return np.linalg.solve(A, b)

    def sew_pose(self, side):
        j = lambda n: self.m.joint(f"openarm_{side}_joint{n}").id
        S = self.to_sew(self._shoulder(side))
        E = self.to_sew(self.d.xanchor[j(4)] - ELBOW_SHIFT * self.d.xaxis[j(4)])
        W = self.to_sew(self.d.xanchor[j(7)])
        R_link7 = self.d.xmat[self.m.body(f"openarm_{side}_link7").id].reshape(3, 3)
        return SEWPose(S=S, E=E, W=W, R_world_wrist=self._R_base().T @ R_link7 @ C_HAND)

    def frame(self, ql, qr):
        """RetargetFrame for the pair of arm configs (runs FK)."""
        self.set_q(ql, qr)
        R = self._R_base()
        return RetargetFrame(
            left_sew=self.sew_pose("left"), right_sew=self.sew_pose("right"),
            R_world_upper_body=R,
            p_world_upper_body=self.d.xpos[self.base] + R @ SEW_ORIGIN)

    # ---- contacts and clearance (call after set_q)
    def contacts(self):
        """Set of contact kinds with penetration: {'arm-arm', 'arm-torso'}."""
        mujoco.mj_collision(self.m, self.d)
        kinds = set()
        for i in range(self.d.ncon):
            c = self.d.contact[i]
            if c.dist >= 0:
                continue
            a, b = self.owner[c.geom1], self.owner[c.geom2]
            if {a, b} == {"left", "right"}:
                kinds.add("arm-arm")
            elif "torso" in (a, b) and a != b:
                # arm link0 is the mount (parent-child pairs are skipped by
                # MuJoCo already); anything else touching the torso counts.
                kinds.add("arm-torso")
        return kinds

    def clearance(self):
        """Min signed mesh distance (m): (arm-arm, arm-torso). Negative = overlap."""
        fromto = np.zeros(6)
        dist = lambda pairs: min(
            mujoco.mj_geomDistance(self.m, self.d, a, b, 0.5, fromto) for a, b in pairs)
        return dist(self.pairs_arm_arm), dist(self.pairs_arm_torso)

    def random_q(self, rng, centre=None, spread=None):
        """Random arm configs. centre=None: uniform over the joint limits;
        otherwise uniform within +-spread rad of `centre`, clipped to limits."""
        if centre is None:
            return {s: rng.uniform(self.lo[s], self.hi[s]) for s in SIDES}
        return {s: np.clip(centre[s] + rng.uniform(-spread, spread, 7),
                           self.lo[s], self.hi[s]) for s in SIDES}


# ---------------------------------------------------------------- solver
class Solver:
    """A src.safety_filter.SafetyFilter whose solve() calls are timed."""

    def __init__(self, filter_on):
        self.sf = SafetyFilter(collision_avoidance=filter_on)
        self.session = self.sf.session
        self.times_ms = []

    def solve(self, frame, q_seed, repeats=1):
        """Solve `frame` `repeats` times in a row (the filter keeps state).

        Returns the output of the first and of the last call, as (ql, qr,
        capsules) where capsules are the filter's post-filter capsules.
        """
        results = []
        self.session.reset(q_seed["right"], q_seed["left"])   # (right, left) order
        for _ in range(repeats):
            t0 = time.perf_counter()
            ql, qr = self.sf.solve(frame, q_seed["left"], q_seed["right"])
            self.times_ms.append(1000.0 * (time.perf_counter() - t0))
            results.append((ql, qr, list(self.session.sew_capsules())))
        return results[0], results[-1]


def filter_displacement(frame, capsules):
    """Largest distance (m) the filter moved any S/E/W point from the input."""
    if not capsules:
        return float("nan")
    pts = {n: (np.asarray(a), np.asarray(b)) for n, a, b, _ in capsules}
    worst = 0.0
    for tag, side in (("L", "left"), ("R", "right")):
        sew = getattr(frame, f"{side}_sew")
        S, E, W = pts[f"{tag}_upper"][0], pts[f"{tag}_upper"][1], pts[f"{tag}_lower"][1]
        for got, want in ((S, sew.S), (E, sew.E), (W, sew.W)):
            worst = max(worst, float(np.linalg.norm(got - want)))
    return worst


# ---------------------------------------------------------------- reports
def pct(x, p):
    return float(np.percentile(x, p))


def timing_line(label, t):
    t = np.asarray(t)
    return (f"  {label:34s} n={len(t):4d}  mean {t.mean():6.3f}  median {np.median(t):6.3f}  "
            f"p95 {pct(t, 95):6.3f}  max {t.max():6.3f} ms")


def joint_errors(q_in, q_out):
    return {s: np.abs(q_out[s] - q_in[s]) for s in SIDES}


def sample_configs(arms, rng, centre, spread, n_free, n_collide, max_draws):
    """Random arm configs split by MuJoCo contact status.

    Returns (free, colliding, draws, kinds_seen): `free` are configs with no
    arm-arm / arm-torso contact, `colliding` are (config, contact kinds) pairs,
    arm-arm cases first (arms crossed / touching).
    """
    n_aa = n_collide // 2               # want at least this many arm-arm cases
    free, colliding, draws, kinds_seen = [], [], 0, {}
    n_arm_arm = lambda: sum("arm-arm" in k for _, k in colliding)
    while draws < max_draws and (len(free) < n_free or len(colliding) < n_collide):
        draws += 1
        q = arms.random_q(rng, centre, spread)
        arms.set_q(q["left"], q["right"])
        kinds = arms.contacts()
        key = "+".join(sorted(kinds)) or "none"
        kinds_seen[key] = kinds_seen.get(key, 0) + 1
        if not kinds:
            if len(free) < n_free:
                free.append(q)
        elif len(colliding) < n_collide:
            room = n_collide - len(colliding)
            if "arm-arm" in kinds or room > max(0, n_aa - n_arm_arm()):
                colliding.append((q, kinds))
    return free, colliding, draws, kinds_seen


def cross_check(arms, sf, n=600, seed=123, tol=1e-9, label=""):
    """Helper frame (solver FK, src.safety_filter) vs MuJoCo-geometry frame.

    Half the configs are within +-0.8 rad of the default pose, half uniform
    over the joint limits. Compares S, E, W and the wrist rotation (both arms).
    """
    rng = np.random.default_rng(seed)
    worst = dict(S=0.0, E=0.0, W=0.0, R=0.0)
    for k in range(n):
        q = arms.random_q(rng, sf.default_q, 0.8) if k < n // 2 else arms.random_q(rng)
        geo = arms.frame(q["left"], q["right"])
        got = sf.frame(q["left"], q["right"])
        for side in SIDES:
            g, h = getattr(geo, f"{side}_sew"), getattr(got, f"{side}_sew")
            worst["S"] = max(worst["S"], np.abs(g.S - h.S).max())
            worst["E"] = max(worst["E"], np.abs(g.E - h.E).max())
            worst["W"] = max(worst["W"], np.abs(g.W - h.W).max())
            worst["R"] = max(worst["R"], np.abs(g.R_world_wrist - h.R_world_wrist).max())
    ok = max(worst.values()) < tol
    print(f"CROSS-CHECK {label}: {n} configs, solver FK (helper) vs MuJoCo geometry: "
          f"max |dS| {worst['S']:.1e}  |dE| {worst['E']:.1e}  |dW| {worst['W']:.1e}  "
          f"|dR_wrist| {worst['R']:.1e}  ->  {'PASS' if ok else 'FAIL'} (tol {tol:g})")
    return ok


def branch_failures(seed=0, spread=0.0, n_free=20, n_collide=8, tol=1e-3,
                    max_draws=200000):
    """Arm configs that do not round-trip with the filter OFF (IK branch jumps).

    Samples exactly like main() with the same seed (defaults reproduce the
    `--spread 0` run), runs each config through a filter-OFF round trip, and
    returns one entry per failing ARM, biggest joint error first:
    dict(arm, q, out, error, joints, source, index).
    """
    arms = Arms()
    off = SafetyFilter(collision_avoidance=False)   # control, test only
    rng = np.random.default_rng(seed)
    centre = off.default_q if spread > 0 else None
    free, colliding, _, _ = sample_configs(arms, rng, centre, spread, n_free,
                                           n_collide, max_draws)
    cases = [("collision-free", i, q) for i, q in enumerate(free)] + \
            [("colliding", i, q) for i, (q, _) in enumerate(colliding)]
    found = []
    for source, index, q in cases:
        out = dict(zip(SIDES, off.filter(q["left"], q["right"])))
        for side in SIDES:
            err = np.abs(out[side] - q[side])
            if err.max() > tol:
                found.append(dict(arm=side, q=q[side].copy(), out=out[side].copy(),
                                  error=float(err.max()), joints=err,
                                  source=source, index=index))
    found.sort(key=lambda e: -e["error"])
    return found


def model_check(sf_off, n=100):
    """Does the combined robot (Tracer + OpenArm) map to the solver by name?"""
    import openarm_teleop
    from src.actuator_mapping import NAME_TO_IDX
    scene = PROJECT_ROOT / "models" / "scenes" / "chemistry_lab_combined.xml"
    arms = Arms(model=scene, contacts=False)
    m = arms.m
    spec = np.load(Path(openarm_teleop.__file__).parent / "assets" / "specs"
                   / "openarm_v1.npz")
    print("=" * 78)
    print(f"MODEL CHECK: {scene.name}")
    print("=" * 78)
    bad = []
    for side in SIDES:
        names = [str(x) for x in spec[f"{side}_arm/joint_names"]]
        for i in range(1, 8):
            jname = f"openarm_{side}_joint{i}"
            aid = mujoco.mj_name2id(m, mujoco.mjtObj.mjOBJ_ACTUATOR, f"{side}_joint{i}_ctrl")
            jid = mujoco.mj_name2id(m, mujoco.mjtObj.mjOBJ_JOINT, jname)
            if jid < 0 or aid < 0:
                bad.append(f"{side} joint{i}: joint or actuator missing")
                continue
            if names[i - 1] != jname:
                bad.append(f"{side} joint{i}: solver expects {names[i - 1]}, model has {jname}")
            if m.actuator_trnid[aid, 0] != jid:
                bad.append(f"{side} joint{i}: actuator drives {m.joint(m.actuator_trnid[aid, 0]).name}")
            if NAME_TO_IDX[f"{side}_joint{i}"] != aid:
                bad.append(f"{side} joint{i}: src.actuator_mapping index {NAME_TO_IDX[f'{side}_joint{i}']} "
                           f"!= model actuator id {aid}")
    print("joint order by name (solver spec order == model joint names == actuator "
          f"targets == src.actuator_mapping indices): {'OK for all 14 arm joints' if not bad else bad}")
    lim = 0.0
    for side in SIDES:
        lo, hi = spec[f"{side}_arm/joint_lower"], spec[f"{side}_arm/joint_upper"]
        lim = max(lim, np.abs(arms.lo[side] - lo).max(), np.abs(arms.hi[side] - hi).max())
    print(f"joint limits, model vs the solver's embedded spec: max difference {lim:.1e} rad")
    cross_check(arms, sf_off, n=600, label="combined model")
    rng = np.random.default_rng(11)
    for label, draw in (("within +-0.8 rad of default", lambda: arms.random_q(rng, sf_off.default_q, 0.8)),
                        ("uniform over joint limits", lambda: arms.random_q(rng))):
        errs = []
        for _ in range(n):
            q = draw()
            arms.set_q(q["left"], q["right"])                  # angles from OUR model ...
            got = {s: arms.d.qpos[arms.qadr[s]].copy() for s in SIDES}   # ... read back by name
            ql, qr = sf_off.filter(got["left"], got["right"])           # filter OFF
            errs.append(max(np.abs(ql - got["left"]).max(), np.abs(qr - got["right"]).max()))
        e = np.asarray(errs)
        print(f"round trip, filter OFF, angles from the combined model, {label}: {n} configs, "
              f"max error {e.max():.2e} rad, exact (<1e-4) in {(e < 1e-4).sum()}/{n}")
    print()


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("--seed", type=int, default=0)
    ap.add_argument("--n-free", type=int, default=20, help="collision-free configs")
    ap.add_argument("--n-collide", type=int, default=8, help="colliding configs")
    ap.add_argument("--repeats", type=int, default=10,
                    help="identical frames per config (the filter keeps state)")
    ap.add_argument("--max-draws", type=int, default=200000)
    ap.add_argument("--spread", type=float, default=0.8,
                    help="sample within +-SPREAD rad of the solver's default arm pose "
                         "(0 = uniform over the full joint limits instead)")
    ap.add_argument("--cross-check-n", type=int, default=600,
                    help="configs for the helper-vs-MuJoCo-geometry cross-check (0 = skip)")
    ap.add_argument("--model-check", action="store_true",
                    help="only check the combined robot model (joint order, limits, "
                         "round trip from its angles), then exit")
    args = ap.parse_args()

    on, off = Solver(True), Solver(False)       # `off` = control, test only
    if args.model_check:
        model_check(off.sf)
        return
    arms = Arms()
    default_q = on.sf.default_q
    rng = np.random.default_rng(args.seed)
    if args.cross_check_n:
        cross_check(arms, off.sf, n=args.cross_check_n, label="Kong's model")

    # ---- sample configs by MuJoCo contact status
    centre = default_q if args.spread > 0 else None
    free, colliding, draws, kinds_seen = sample_configs(
        arms, rng, centre, args.spread, args.n_free, args.n_collide, args.max_draws)
    n_arm_arm = lambda: sum("arm-arm" in k for _, k in colliding)
    how = (f"within +-{args.spread} rad of the solver's default arm pose"
           if args.spread > 0 else "uniform over the joint limits")
    print(f"\nSampled {draws} random configs ({how}): {kinds_seen}")
    print(f"Collision-free: {len(free)}, colliding kept: {len(colliding)} "
          f"({n_arm_arm()} with arm-arm contact)")
    print("Collision geoms enabled in memory; MuJoCo uses mesh convex hulls.\n")

    # ================= 3. collision-free test
    print("=" * 78)
    print("COLLISION-FREE CONFIGS: input joints -> frame -> solve() -> output joints")
    print("=" * 78)
    for seed_name in ("seeded with the input pose", "seeded with default_q (hard seed)"):
        errs_on1, errs_onN, errs_off, disp, clr = [], [], [], [], []
        per_joint = {s: [] for s in SIDES}
        for q in free:
            frame = on.sf.frame(q["left"], q["right"])
            arms.set_q(q["left"], q["right"])
            clr.append(arms.clearance())
            seed = q if seed_name.startswith("seeded with the") else default_q
            first, last = on.solve(frame, seed, args.repeats)
            ctrl, _ = off.solve(frame, seed, 1)
            e1 = joint_errors(q, {"left": first[0], "right": first[1]})
            eN = joint_errors(q, {"left": last[0], "right": last[1]})
            ec = joint_errors(q, {"left": ctrl[0], "right": ctrl[1]})
            errs_on1.append(max(e1["left"].max(), e1["right"].max()))
            errs_onN.append(max(eN["left"].max(), eN["right"].max()))
            errs_off.append(max(ec["left"].max(), ec["right"].max()))
            disp.append(filter_displacement(frame, first[2]))
            for s in SIDES:
                per_joint[s].append(e1[s])
        a1, aN, a0 = map(np.asarray, (errs_on1, errs_onN, errs_off))
        print(f"\n[{seed_name}]  (max |joint error| per config, radians)")
        print(f"  filter ON, 1st solve : max {a1.max():.4f}  mean {a1.mean():.4f}  "
              f"median {np.median(a1):.4f}  configs < 1e-3: {(a1 < 1e-3).sum()}/{len(a1)}")
        print(f"  filter ON, after {args.repeats:2d}  : max {aN.max():.4f}  mean {aN.mean():.4f}  "
              f"median {np.median(aN):.4f}  configs < 1e-3: {(aN < 1e-3).sum()}/{len(aN)}")
        print(f"  CONTROL filter OFF   : max {a0.max():.4f}  mean {a0.mean():.4f}  "
              f"configs < 1e-3: {(a0 < 1e-3).sum()}/{len(a0)}   (frame conversion by itself)")
        d_ = np.asarray(disp)
        print(f"  filter moved S/E/W points by up to {1000 * np.nanmax(d_):.1f} mm "
              f"(median {1000 * np.nanmedian(d_):.1f} mm)")
        for s in SIDES:
            print(f"  per-joint max error, {s:5s} arm (j1..j7): "
                  f"{np.max(per_joint[s], axis=0)}")
        if seed_name.startswith("seeded with the"):
            c = np.asarray(clr)
            print(f"  input clearance (mesh): arm-arm min {1000 * c[:, 0].min():.0f} mm, "
                  f"arm-torso min {1000 * c[:, 1].min():.0f} mm")
            print("  per config: error ON | OFF | filter shift mm | clearance arm-arm / arm-torso mm")
            for k in range(len(free)):
                flag = "  <--" if a1[k] > 1e-3 else ""
                print(f"   {k:2d}: {a1[k]:.4f} | {a0[k]:.4f} | "
                      f"{1000 * disp[k]:6.1f} | {1000 * clr[k][0]:6.0f} / {1000 * clr[k][1]:5.0f}{flag}")

    # ================= 4. collision test
    print("\n" + "=" * 78)
    print("COLLIDING CONFIGS (arms crossed / touching, or arm on torso)")
    print("=" * 78)
    for k, (q, _) in enumerate(colliding):
        frame = on.sf.frame(q["left"], q["right"])
        arms.set_q(q["left"], q["right"])
        before = sorted(arms.contacts())
        clr_b = arms.clearance()
        first, last = on.solve(frame, q, args.repeats)
        ctrl, _ = off.solve(frame, q, 1)
        print(f"\nconfig {k}: contacts before = {before}; clearance arm-arm "
              f"{1000 * clr_b[0]:.0f} mm, arm-torso {1000 * clr_b[1]:.0f} mm")
        for tag, res in (("1st solve", first), (f"after {args.repeats}", last)):
            out = {"left": res[0], "right": res[1]}
            if out["left"] is None or out["right"] is None:
                print(f"  {tag}: solver returned None for a side")
                continue
            arms.set_q(out["left"], out["right"])
            after = sorted(arms.contacts())
            clr_a = arms.clearance()
            err = joint_errors(q, out)
            print(f"  {tag:10s}: contacts after = {after or 'none (contact-free)'}; "
                  f"clearance arm-arm {1000 * clr_a[0]:.0f} mm, arm-torso {1000 * clr_a[1]:.0f} mm")
            for s in SIDES:
                print(f"      {s:5s} joint change |dq| (j1..j7): {err[s]}   max {err[s].max():.3f}")
        cl = np.abs(ctrl[0] - q["left"]).max(), np.abs(ctrl[1] - q["right"]).max()
        print(f"  control (filter OFF) round-trip error: left {cl[0]:.4f}, right {cl[1]:.4f}")

    # ================= 5. timing
    print("\n" + "=" * 78)
    print("TIMING of session.solve() (ms)")
    print("=" * 78)
    print(timing_line("filter ON  (all calls)", on.times_ms))
    print(timing_line("filter OFF (control, all calls)", off.times_ms))
    print()


if __name__ == "__main__":
    main()
